/* UI uses the existing profile store and its conflict/rollback protections. */
function trainingHistory(){
 const rows=FormTraining.history(data,'9999-12-31'),verified=rows.filter(h=>h.date<=currentDay()&&h.sets.length),ids=[...new Set(verified.flatMap(h=>h.sets.map(s=>s.exerciseId)))];
 return '<section class="section panel"><h2>Performance explorer</h2><p class="muted tiny">Confirmed sets through today only. Drafts and future dates are excluded. Records compare the same movement and unit; loads are entered external loads.</p><label class="field">Movement<select id="historyMovement" data-action-change="drawPerformance()"><option value="">All movements · volume</option>'+ids.map(id=>'<option value="'+esc(id)+'">'+esc(FormSession.exercise(verified.find(h=>h.sets.some(s=>s.exerciseId===id)).log,id,data.exercises)?.name||id)+'</option>').join('')+'</select></label><div class="row"><label class="field">Recorded unit<select id="historyUnit" data-action-change="drawPerformance()"><option value="strength">Strength repetitions</option><option value="reps">Repetitions</option><option value="seconds">Seconds</option><option value="unknown">Unknown legacy unit</option></select></label><label class="field">Chart<select id="historyMetric" data-action-change="drawPerformance()"><option value="reps">Repetitions / seconds</option><option value="load">External load</option><option value="volume">Volume</option></select></label></div><div id="performancePlot"></div><h3>Session history</h3><div class="history-list">'+(rows.length?rows.map(h=>'<button class="ghost history-row" data-history-date="'+h.date+'" data-history-session="'+esc(h.sessionId||'')+'"><strong>'+fmt(h.date)+'</strong><span>'+esc(h.log.plan?.routine.name||'Recorded session')+'</span><small>'+(h.date>currentDay()?'Future date · excluded from reports · ':'')+h.sets.length+' confirmed · '+Math.round(h.volume)+' kg × reps'+(h.sets.length?'':' · incomplete / skipped')+'</small></button>').join(''):'<p>No recorded sessions yet.</p>')+'</div></section>';
}
function drawPerformance(){
 const el=document.getElementById('performancePlot');if(!el)return;
 const id=document.getElementById('historyMovement').value,unit=document.getElementById('historyUnit').value,metric=document.getElementById('historyMetric').value;
 const all=FormTraining.history(data,currentDay()).filter(h=>h.sets.length).reverse();
 const rows=all.map(h=>{const e=id?recordExercise(h.date,id,h.sessionId):null,sets=h.sets.filter(s=>!id||(s.exerciseId===id&&e?.kind===unit));
 const usable=metric==='load'?sets.filter(s=>s.weight!==null):sets;
 const value=!id?h.volume:metric==='load'?Math.max(0,...usable.map(s=>s.weight)):metric==='volume'?usable.reduce((n,s)=>n+(s.weight||0)*s.reps,0):Math.max(0,...usable.map(s=>s.reps));return {...h,sets:usable,e,value}}).filter(h=>h.sets.length);
 const valid=!(id&&['seconds','unknown'].includes(unit)&&metric!=='reps');
 if(!valid){el.innerHTML='<p class="empty">Choose repetitions / seconds for this unit. Load and volume comparisons are available for repetition-based movements.</p>';return}
 const max=Math.max(1,...rows.map(h=>h.value)),record=id?FormTraining.records(data,id,unit,currentDay()):null;
 const unitLabel=unit==='seconds'?'seconds':unit==='unknown'?'unknown units':'reps';
 el.innerHTML=(record?'<div class="notice">Best confirmed set: '+(record.repetitions?record.repetitions.reps+' '+unitLabel+' on '+record.repetitions.date:'No matching records')+(record.load?' · Highest entered load: '+record.load.weight+' kg on '+record.load.date:'')+'</div>':'')+'<p class="tiny">'+(!id?'Confirmed external-load volume per session.':metric==='load'?'Highest confirmed external load (kg).':metric==='volume'?'Confirmed external-load volume (kg × reps).':'Best confirmed '+unitLabel+' per session.')+'</p><div class="performance-bars">'+rows.slice(-24).map(h=>'<button class="ghost" data-history-date="'+h.date+'" data-history-session="'+esc(h.sessionId||'')+'" title="Open '+h.date+'"><span style="height:'+Math.max(2,h.value/max*100)+'px"></span><b>'+Math.round(h.value*100)/100+'</b><small>'+h.date.slice(5)+'</small></button>').join('')+'</div>'+(rows.length?'':'<p class="empty">No confirmed records for this selection.</p>')+(id?'<div class="history-list">'+rows.map(h=>'<p>'+h.date+' · '+Math.max(...h.sets.map(s=>s.reps))+' '+unitLabel+' · highest entered load '+(h.sets.some(s=>s.weight!==null)?Math.max(...h.sets.filter(s=>s.weight!==null).map(s=>s.weight))+' kg':'unknown')+'</p>').join(''):'');
}
function progressionPanel(){return '<section class="section panel"><h2>Progression reviews</h2><p>Review confirmed results on two separate dates before proposing sets, repetition/duration, rest and load targets. This is an evidence review, not an automatic recommendation of readiness. Keep prescribed changes aligned with clinician guidance.</p><button class="secondary" data-action-click="newProgression()">Create target review</button>'+progressionRulesHtml()+reviewSignalsHtml()+(data.progressionReviews||[]).slice().reverse().map(p=>'<div class="review-card"><strong>'+esc(data.exercises.find(e=>e.id===p.exercise)?.name||p.exercise)+'</strong><p>'+p.reps+' '+(p.kind==='seconds'?'seconds':'reps')+' · '+esc(p.status)+' · '+esc(data.routines.find(r=>r.id===p.routine)?.name||p.routine)+'</p>'+(p.previous?'<p class="tiny">Before: '+esc(targetDescription(p.previous))+'</p>':'')+(p.target?'<p class="tiny">Proposed: '+esc(targetDescription(p.target))+'</p>':'')+(p.evidence?'<p class="tiny">Evidence: '+p.evidence.map(e=>esc(e.date)+' ('+e.sets.length+' confirmed sets)').join(' · ')+'</p>':'')+(p.note?'<p>'+esc(p.note)+'</p>':'')+(p.resolved?'<p class="tiny">Resolved '+esc(p.resolved)+'</p>':'')+(p.status==='pending'?'<button class="primary" data-review-approve="'+p.id+'">Review & approve</button> <button class="ghost" data-review-dismiss="'+p.id+'">Dismiss</button>':'')+'</div>').join('')+'</section>'}
function trainingDialog(title,body,submit){const assertContext=editingContext();const d=document.createElement('dialog');d.className='panel program-editor';d.setAttribute('aria-label',title);d.innerHTML='<form><h2>'+title+'</h2>'+body+'<p role="alert"></p><div class="row program-actions"><button class="primary">Save</button><button type="button" class="ghost" data-cancel>Cancel</button></div></form>';d.querySelector('[data-cancel]').onclick=()=>d.close();d.onclose=()=>d.remove();d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{assertContext();if(await submit(d)!==false)d.close()}catch(error){d.querySelector('[role=alert]').textContent=error.message}};document.body.append(d);d.showModal();return d}
function targetDescription(t){return t.sets+' sets × '+t.reps+' '+(t.kind==='seconds'?'seconds':'reps')+' · '+(t.rest===null?'rest not supplied':t.rest+'s rest')+' · loads '+(t.weights.length?t.weights.map(w=>w===null?'unknown':w+' kg').join(', '):'unknown')}
function newProgression(routineId,exerciseId){
 const options=data.routines.flatMap(r=>r.ids.filter(id=>!FormPreferences.blocked(data,id)&&new Set(FormTraining.evidence(data,id,currentDay(),r.id).map(h=>h.date)).size===2&&!(data.progressionReviews||[]).some(p=>p.status==='pending'&&p.routine===r.id&&p.exercise===id)).map(id=>({r,id})));
 if(!options.length){alert('Use confirmed results on two separate dates, resolve existing reviews, and check exercise preferences in Settings.');return}
 const profile=activeProfile,sourceStore=store;
 const d=trainingDialog('Create target review','<label class="field">Workout and movement<select name="movement">'+options.map((o,i)=>'<option value="'+i+'">'+esc(o.r.name+' · '+ex(o.id).name)+'</option>').join('')+'</select></label><div data-evidence></div><p class="notice">Enter your own reviewed targets. No load or readiness is inferred. Approval updates the normal routine. Dated training plans and saved sessions retain their targets.</p><div class="program-fields"><label>Proposed sets<input name="sets" type="number" min="1" max="100" step="1" required></label><label>Proposed reps / seconds<input name="target" type="number" min="0" step="1" required></label><label>Rest seconds<input name="rest" type="number" min="0" step="1" required></label></div><label class="field">Loads by set (kg)<input name="weights" placeholder="Blank means unknown; separate loads with commas"></label><details><summary>Calculate from my chosen increment</summary><p class="tiny">Optional arithmetic using your own increment after two matching, fully confirmed sessions. This does not assess readiness or choose a clinically appropriate increase.</p><label class="field">Change<select name="incrementMetric"><option value="reps">Repetitions / seconds</option><option value="load">External load per set (kg)</option></select></label><label class="field">My increment<input name="increment" type="number" min="0.001" step="any"></label><button type="button" class="secondary" data-calculate>Calculate draft target</button><p data-calculation role="status"></p></details><label class="field">Reason / guidance reviewed<textarea name="note"></textarea></label>',async dialog=>{
  if(activeProfile!==profile||store!==sourceStore)throw Error('Profile changed. Reopen this review.');const o=options[Number(dialog.querySelector('select').value)],raw=dialog.querySelector('[name=weights]').value,target={...FormTraining.target(data,o.r.id,o.id),sets:Number(dialog.querySelector('[name=sets]').value),rest:Number(dialog.querySelector('[name=rest]').value),weights:raw.trim()?raw.split(',').map(w=>w.trim()===''?null:Number(w)):[]};const p=FormTraining.propose(data,o.r.id,o.id,Number(dialog.querySelector('[name=target]').value),currentDay(),{target,note:dialog.querySelector('[name=note]').value});data.progressionReviews=(data.progressionReviews||[]).concat(p);if(!await save())return false;render()
 });
 const show=()=>{const o=options[Number(d.querySelector('select').value)],target=FormTraining.target(data,o.r.id,o.id);d.querySelector('[data-evidence]').textContent='Normal routine target: '+targetDescription(target)+'. Confirmed actuals: '+FormTraining.evidence(data,o.id,currentDay(),o.r.id).map(h=>h.date+': '+h.sets.map(s=>s.reps+' '+(target.kind==='seconds'?'seconds':'reps')+' @ '+(s.weight??'unknown')+' kg').join(', ')).join(' | ')+(data.restrictions?' Saved guidance: '+data.restrictions:'');d.querySelector('[name=sets]').value=target.sets;d.querySelector('[name=rest]').value=target.rest;d.querySelector('[name=weights]').value=target.weights.map(w=>w??'').join(', ');d.querySelector('[name=target]').value='';d.querySelector('[data-calculation]').textContent=''};
 const preferred=options.findIndex(o=>o.r.id===routineId&&o.id===exerciseId);if(preferred>=0)d.querySelector('select').value=String(preferred);d.querySelector('select').onchange=show;d.querySelector('[data-calculate]').onclick=()=>{try{if(activeProfile!==profile||store!==sourceStore)throw Error('Profile changed. Reopen this review.');const o=options[Number(d.querySelector('select').value)],metric=d.querySelector('[name=incrementMetric]').value,increment=Number(d.querySelector('[name=increment]').value),t=FormTraining.calculateTarget(data,o.r.id,o.id,currentDay(),metric,increment);d.querySelector('[name=sets]').value=t.sets;d.querySelector('[name=target]').value=t.reps;d.querySelector('[name=rest]').value=t.rest;d.querySelector('[name=weights]').value=t.weights.map(w=>w??'').join(', ');d.querySelector('[data-calculation]').textContent='Draft only: '+targetDescription(t)+'. Review before saving and approving.'}catch(error){d.querySelector('[data-calculation]').textContent=error.message}};show();
}

function planningPanel(){const blocks=data.trainingBlocks||[];return '<section class="section panel"><h2>Long-term training framework</h2><p>Four-week planning blocks with reassessment and recovery notes. These notes do not change workouts, loads or completion records.</p>'+(!blocks.length?'<label class="field">Planning start date<input id="planningStart" type="date" min="1900-01-01" max="9998-01-01" value="'+(activeProfile==='Ben'?'2026-10-13':currentDay())+'"></label>':'')+'<button class="secondary" data-action-click="extendPlanning()">'+(blocks.length?'Extend by 52 weeks':'Create 52-week framework')+'</button> <button class="ghost" data-action-click="editSchedule()">Edit weekly availability</button>'+periodPlansHtml()+'<div class="history-list">'+blocks.map((b,i)=>'<button class="ghost history-row" data-block="'+i+'"><strong>'+b.start+' – '+b.end+'</strong><span>'+esc(b.focus)+'</span><small>'+(b.reviewType==='annual'?'Annual review · ':'')+(b.reviewed?'Reviewed':b.reviewEntries?.length?'Interim review saved · next review '+b.review:(b.review<=currentDay()?'Review due now · ':'Review due ')+b.review)+' · '+esc(b.recovery)+'</small></button>').join('')+'</div></section>'}
async function extendPlanning(){try{const blocks=data.trainingBlocks||[],start=blocks.length?FormTraining.day(blocks.at(-1).end,1):document.getElementById('planningStart').value;if(!FormCalendar.validDate(start))throw Error('Choose a valid planning start date.');data.trainingBlocks=blocks.concat(FormTraining.blocks(start));if(await save())render()}catch(e){alert(e.message)}}
function blockReportText(report){if(!report.through)return 'This block has not started. No results are inferred.';const describe=t=>t.sessions+' sessions with confirmed sets · '+t.sets+' sets · '+Math.round(t.volume)+' kg × reps · '+Math.round(t.minutes)+' activity minutes';return (report.from?'From '+report.from+' through ':'Through ')+report.through+': '+describe(report.current)+'. Previous equal-length period ('+report.previous.from+' to '+report.previous.to+'): '+describe(report.previous)+'. '+report.drafts+' draft sets excluded; '+report.skipped+' movements with remaining sets skipped. Counts are not an adherence or readiness score.'}
function editBlock(i){const b=data.trainingBlocks[i],profile=activeProfile,sourceStore=store,start=b.start;trainingDialog('Review training block','<p>'+b.start+' – '+b.end+(b.reviewType==='annual'?' · Annual checkpoint':'')+'</p><p class="notice">'+esc(blockReportText(FormTraining.blockReport(data,b,currentDay())))+'</p><label class="field">Goals and focus<textarea name="focus" required>'+esc(b.focus)+'</textarea></label><label class="field">Recovery and reassessment notes<textarea name="recovery">'+esc(b.recovery)+'</textarea></label><label class="field">Review conclusions<textarea name="note"></textarea></label><label><input name="reviewed" type="checkbox"> Record a review entry today</label><p class="tiny">Saving goals does not change prescribed exercises, loads or your calendar. A review entry retains today’s evidence even after historical corrections.</p>'+(b.reviewEntries?.length?'<details><summary>Previous reviews ('+b.reviewEntries.length+')</summary>'+b.reviewEntries.slice().reverse().map(e=>'<article class="review-card"><strong>'+esc(e.date+' · '+e.focus)+'</strong><p>'+esc(e.note)+'</p><p class="tiny">'+esc(blockReportText(e.report))+'</p></article>').join('')+'</details>':''),async d=>{if(activeProfile!==profile||store!==sourceStore||data.trainingBlocks?.[i]?.start!==start)throw Error('Profile or block changed. Reopen the review.');data=FormTraining.saveBlock(data,i,{focus:d.querySelector('[name=focus]').value,recovery:d.querySelector('[name=recovery]').value,note:d.querySelector('[name=note]').value,reviewed:d.querySelector('[name=reviewed]').checked},currentDay());if(!await save())return false;render()})}

function editSessionNotes(){trainingDialog('Session notes','<p>Record session-specific instructions or modifications. Saved prescriptions and actual sets remain separate.</p><label class="field">Notes<textarea name="note">'+esc(activeLog()?.sessionNote||'')+'</textarea></label>',async d=>{FormProgram.record(data,activeProfile,selected,activeSessionId).sessionNote=d.querySelector('textarea').value;if(!await save())return false;render()})}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{if(b.dataset.historyDate){stopTimer();activeSessionId=b.dataset.historySession||'';selected=b.dataset.historyDate;view='Workout';render()}if(b.dataset.block!==undefined)editBlock(Number(b.dataset.block));const id=b.dataset.reviewApprove||b.dataset.reviewDismiss;if(id){if(b.dataset.reviewApprove&&!confirm('Apply this reviewed target to the normal routine? Dated training plans and existing primary and extra session snapshots remain unchanged. Confirm that you reviewed the before/after values, evidence and clinician guidance.'))return;data=FormTraining.resolve(data,activeProfile,id,b.dataset.reviewApprove?'approve':'dismiss',currentDay());if(await save())render()}}catch(e){alert(e.message)}});
function editSessionTarget(id){const log=activeLog(),original=FormProgram.plan(data,activeProfile,selected,activeSessionId).exercises.find(e=>e.id===id);if(log?.sets.some(s=>s.exerciseId===id)||log?.changes?.[id]){alert('This movement has recorded entries or a skip/substitution. Correct actual values using its set controls; targets remain preserved.');return}const e={...original,...log?.targetEdits?.[id]};trainingDialog('Edit this session’s targets','<p>Applies to this date only. Original prescriptions are retained. No sets will be confirmed.</p><label class="field">Sets<input name="sets" type="number" min="1" max="100" step="1" required value="'+e.sets+'"></label><label class="field">Reps / seconds<input name="reps" type="number" min="0" step="1" required value="'+e.reps+'"></label><label class="field">Rest seconds<input name="rest" type="number" min="0" step="1" required value="'+(e.rest??'')+'"></label><label class="field">Loads by set (kg)<input name="weights" value="'+esc(e.weights.map(w=>w??'').join(', '))+'" placeholder="Blank means unknown"></label>',async d=>{const target={...e};for(const k of ['sets','reps','rest'])target[k]=Number(d.querySelector('[name='+k+']').value);const raw=d.querySelector('[name=weights]').value;target.weights=raw.trim()?raw.split(',').map(w=>w.trim()===''?null:Number(w)):[];if(target.weights.length>target.sets||target.weights.some(w=>w!==null&&(!Number.isFinite(w)||w<0)))throw Error('Enter no more than one non-negative load per set.');const l=FormProgram.record(data,activeProfile,selected,activeSessionId);l.targetEdits={...l.targetEdits,[id]:Object.fromEntries(['sets','reps','rest','weights','kind'].map(k=>[k,target[k]]))};if(!await save())return false;render()})}
document.addEventListener('click',event=>{const b=event.target.closest('[data-session-target]');if(b)editSessionTarget(b.dataset.sessionTarget)});
function progressShortcuts(){return '<label class="field progress-shortcuts">Jump to section<select aria-label="Progress section" data-action-change="jumpProgress(this.value)"><option value="">Choose a section</option>'+['Performance explorer','Weekly training','Progression reviews','Long-term training framework','Activities','Your training review','Body measurements','Custom measurements'].map(t=>'<option>'+t+'</option>').join('')+'</select></label>'}
function jumpProgress(title){if(progressGroups[title]){progressSection=progressGroups[title];applyProgressSection()}const h=[...document.querySelectorAll('#app h2')].find(h=>h.textContent===title);if(h){h.tabIndex=-1;h.focus({preventScroll:true});h.scrollIntoView({behavior:'smooth',block:'start'})}}
function annualCalendar(){const year=month.getFullYear();return '<section class="panel section"><div class="row between"><h2>Year overview</h2><label class="field">Year<input aria-label="Calendar year" type="number" min="1900" max="9998" value="'+year+'" data-action-change="changeCalendarYear(this.value)"></label></div><p class="tiny muted">Planned days are separate from dates with confirmed sets. A date with one confirmed set is not necessarily a completed workout.</p><div class="year-grid">'+Array.from({length:12},(_,m)=>{const days=new Date(year,m+1,0).getDate();let planned=0,recorded=0;for(let d=1;d<=days;d++){const date=year+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');if(routineFor(date)||(data.extraSessions||[]).some(s=>s.date===date))planned++;if(date<=currentDay()&&confirmed(date).length)recorded++}return '<button class="ghost history-row" data-calendar-month="'+m+'"><strong>'+new Date(year,m,1).toLocaleDateString('en-AU',{month:'long'})+'</strong><small>'+planned+' planned · '+recorded+' recorded</small></button>'}).join('')+'</div></section>'}
function changeCalendarYear(value){const y=Number(value);if(Number.isInteger(y)&&y>=1900&&y<=9998){calendarDate(iso(new Date(y,month.getMonth(),1)))}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-calendar-month]');if(b){month=new Date(month.getFullYear(),Number(b.dataset.calendarMonth),1);selected=iso(month);calendarView='Month';render();document.getElementById('app').scrollIntoView({behavior:'smooth'})}});
function activityTrends(){const rows=(data.activities||[]).filter(a=>a.confirmed&&a.date<=currentDay()),groups=new Map();for(const a of rows){const g=groups.get(a.category)||{count:0,minutes:0,distance:0,known:0};g.count++;g.minutes+=a.minutes;if(a.distanceKm!==null){g.distance+=a.distanceKm;g.known++}groups.set(a.category,g)}return '<section class="panel section"><h2>Activity totals</h2><p class="tiny muted">Confirmed activities through today, grouped by activity. Distance totals include only entries with a supplied distance.</p>'+(groups.size?Array.from(groups,([name,g])=>'<div class="review-card"><strong>'+esc(name)+'</strong><p>'+g.count+' activities · '+Math.round(g.minutes)+' minutes · '+(g.known?Math.round(g.distance*100)/100+' km across '+g.known+' entries':'distance not recorded')+'</p></div>').join(''):'<p>No confirmed activities yet.</p>')+'</section>'}
function measurementTrend(){const rows=data.measurements.filter(m=>m.date<=currentDay()).slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-24);if(!rows.length)return '';const low=Math.min(...rows.map(m=>m.weight)),high=Math.max(...rows.map(m=>m.weight));return '<section class="panel section"><h2>Recorded weight trend</h2><p class="tiny muted">Latest '+rows.length+' entered measurements. Bars use a relative range; labels show actual kilograms. These are measurements, not inferred workout results.</p><div class="performance-bars">'+rows.map(m=>'<button class="measurement-bar ghost" data-action-click="editBodyMeasurement('+data.measurements.indexOf(m)+')"><span style="height:'+(20+(m.weight-low)/Math.max(1,high-low)*80)+'px"></span><strong>'+m.weight+' kg</strong><small>'+esc(m.date)+'</small></button>').join('')+'</div></section>'}
var activeSessionId='';
function activeLog(){return activeSessionId?data.extraSessions?.find(s=>s.id===activeSessionId&&s.date===selected)?.log:data.logs[selected]}
function activeConfirmed(){return (activeLog()?.sets||[]).filter(s=>s.confirmed)}
function sessionPicker(){return '<div class="panel row" style="margin:16px 0"><label class="field">Session on this date<select aria-label="Session on this date" data-action-change="selectActiveSession(this.value)"><option value="">Primary session</option>'+(data.extraSessions||[]).filter(s=>s.date===selected).map((s,i)=>'<option value="'+esc(s.id)+'"'+(s.id===activeSessionId?' selected':'')+'>'+esc((i+2)+'. '+s.log.plan.routine.name)+'</option>').join('')+'</select></label><button class="secondary" data-action-click="addDaySession()">Add another session</button>'+(activeSessionId?'<button class="ghost" data-action-click="moveExtraSession()">Reschedule session</button>':'')+'</div>'}
function addDaySession(){trainingDialog('Add another session','<p>'+fmt(selected)+'. A separate saved plan will be created; no performance is assumed.</p><label class="field">Workout<select name="routine">'+data.routines.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+'</option>').join('')+'</select></label>',async dialog=>{const rid=dialog.querySelector('select').value,reference={...data,logs:{},overrides:{...data.overrides,[selected]:rid}},plan=FormProgram.plan(reference,activeProfile,selected),id='session-'+crypto.randomUUID();data.extraSessions=(data.extraSessions||[]).concat({id,date:selected,log:{date:selected,sets:[],plan}});if(!await save())return false;stopTimer();activeSessionId=id;render()})}

function daySkipped(date){const logs=FormSession.entries(data).filter(([d])=>d===date).map(([,log])=>log);if(routineFor(date)&&!data.logs[date])return false;return logs.length>0&&logs.every(log=>FormSession.summary(log).allSkipped)}
function customMetrics(){const rows=data.customMetrics||[],series=[...new Set(rows.map(m=>JSON.stringify([m.name,m.unit])))];return '<section class="panel section"><h2>Custom measurements</h2><p class="tiny muted">Record body measurements or fitness test results with your own name and unit. These entries stay separate from workout completion.</p><div class="row"><button class="secondary" data-action-click="editMetric()">Add measurement</button><button class="ghost" data-action-click="exportMetrics()">Export measurements CSV</button></div>'+(series.length?'<label class="field">Measurement trend<select id="metricSeries" data-action-change="drawMetricTrend()">'+series.map(key=>'<option value="'+esc(key)+'">'+esc(JSON.parse(key).join(' · '))+'</option>').join('')+'</select></label><div id="metricTrend"></div>':'')+'<div class="history-list">'+rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(m=>'<button class="ghost history-row" data-metric="'+esc(m.id)+'"><strong>'+esc(m.name)+' · '+m.value+' '+esc(m.unit)+'</strong><small>'+m.date+' · Edit / correct</small></button>').join('')+'</div></section>'}
function editMetric(id){const m=data.customMetrics?.find(m=>m.id===id);trainingDialog(m?'Correct measurement':'Add measurement','<label class="field">Date<input type="date" name="date" required value="'+(m?.date||currentDay())+'"></label><label class="field">Measurement name<input name="name" required maxlength="80" placeholder="For example: chest circumference" value="'+esc(m?.name||'')+'"></label><label class="field">Value<input type="number" name="value" min="0" step="any" required value="'+(m?.value??'')+'"></label><label class="field">Unit<input name="unit" required maxlength="24" placeholder="For example: cm" value="'+esc(m?.unit||'')+'"></label><label class="field">Notes<textarea name="notes">'+esc(m?.notes||'')+'</textarea></label>',async d=>{const val=n=>d.querySelector('[name='+n+']').value,entry={id:m?.id||'metric-'+crypto.randomUUID(),date:val('date'),name:val('name').trim(),unit:val('unit').trim(),value:Number(val('value')),notes:val('notes'),updatedAt:new Date().toISOString()};if(!entry.name||!entry.unit)throw Error('Enter a name and unit.');data.customMetrics=(data.customMetrics||[]).filter(x=>x.id!==entry.id).concat(entry);if(!await save())return false;render()})}
function exportMetrics(){downloadCSV('form-'+activeProfile.toLowerCase()+'-measurements.csv',[['date','measurement','value','unit','notes'],...data.measurements.flatMap(m=>[[m.date,'Body weight',m.weight,'kg',''],...(m.waist?[[m.date,'Waist',m.waist,'cm','']]:[])]),...(data.customMetrics||[]).map(m=>[m.date,m.name,m.value,m.unit,m.notes])])}
document.addEventListener('click',event=>{const b=event.target.closest('[data-metric]');if(b)editMetric(b.dataset.metric)});
function moveExtraSession(){rescheduleCalendarSession(selected,activeSessionId)}
function drawMetricTrend(){const el=document.getElementById('metricTrend'),select=document.getElementById('metricSeries');if(!el||!select?.value)return;const [name,unit]=JSON.parse(select.value),rows=(data.customMetrics||[]).filter(m=>m.name===name&&m.unit===unit&&m.date<=currentDay()).slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-24),min=Math.min(...rows.map(m=>m.value)),max=Math.max(...rows.map(m=>m.value));el.innerHTML='<p class="tiny muted">Latest entered values through today. Bars use a relative range; values and units are labelled. Select a bar to correct its record.</p><div class="performance-bars">'+rows.map(m=>'<button class="ghost measurement-bar" data-metric="'+esc(m.id)+'"><span style="height:'+(20+(m.value-min)/Math.max(1,max-min)*80)+'px"></span><strong>'+m.value+' '+esc(m.unit)+'</strong><small>'+m.date+'</small></button>').join('')+'</div>'+(rows.length?'':'<p>No entries through today.</p>')}
function editBodyMeasurement(index){const m=data.measurements[index];trainingDialog('Correct body measurement','<label class="field">Date<input name="date" type="date" required value="'+m.date+'"></label><label class="field">Weight (kg)<input name="weight" type="number" min="20" max="400" step="0.1" required value="'+m.weight+'"></label><label class="field">Waist (cm, optional)<input name="waist" type="number" min="0" step="0.1" value="'+esc(m.waist||'')+'"></label>',async d=>{data.measurements[index]={...m,date:d.querySelector('[name=date]').value,weight:Number(d.querySelector('[name=weight]').value),waist:d.querySelector('[name=waist]').value||null};if(!await save())return false;render()})}
var overviewRequested=false;
var workoutFocus={key:'',enabled:false,id:''};
function workoutToolbar(plan){
 const key=activeProfile+':'+selected+':'+activeSessionId,steps=FormPlayer.sequence(plan,activeLog()?.targetEdits);
 if(workoutFocus.key!==key)workoutFocus={key,overview:overviewRequested,enabled:false,id:plan.routine.ids[0]||'@warmup'};
 overviewRequested=false;
 if(!steps.some(s=>s.id===workoutFocus.id))workoutFocus.id=steps[0].id;
 return '<button class="ghost overview-return" data-show-overview>← Workout overview</button><div class="workout-toolbar" aria-label="Workout navigation"><div class="player-phases">'+Object.entries(FormPlayer.phases).map(([id,name])=>'<button class="ghost" data-player-phase="'+id+'">'+name+'</button>').join('')+'</div><div class="row between"><button class="primary" id="focusToggle" aria-pressed="'+workoutFocus.enabled+'" data-action-click="toggleWorkoutFocus()">'+(workoutFocus.enabled?'Show all exercises':'Open workout player')+'</button><button class="ghost timer compact-timer" id="focusTimer" aria-label="Rest timer" data-action-click="stopTimer()">00:00</button><button class="ghost" data-action-click="stopTimer()">Stop rest</button></div><div class="row"><label class="field">Exercise picker<select aria-label="Jump to exercise" data-action-change="jumpWorkoutExercise(this.value)">'+steps.map(s=>'<option value="'+esc(s.id)+'"'+(s.id===workoutFocus.id?' selected':'')+'>'+FormPlayer.phases[s.phase]+' · '+esc(s.name)+'</option>').join('')+'</select></label></div><div class="row focus-options"><label><input type="checkbox" aria-label="Auto-start rest" '+(autoRestEnabled?'checked':'')+' data-action-change="setAutoRest(this.checked)"> Rest after confirming</label><button class="ghost" data-action-click="nextUnfinishedExercise()">Next unfinished</button><button class="ghost" data-edit-sequence>Edit future sequence</button></div><p class="tiny muted" id="focusPosition" aria-live="polite"></p></div>';
}
function applyWorkoutFocus(){
 if(document.querySelector('.empty-workout')){document.getElementById('app').classList.remove('player-active','overview-active');return}
 const plan=FormProgram.plan(data,activeProfile,selected,activeSessionId),steps=FormPlayer.sequence(plan,activeLog()?.targetEdits),index=steps.findIndex(s=>s.id===workoutFocus.id),current=steps[index];
 const sections=[...document.querySelectorAll('[data-player-step]')];
 document.getElementById('app').classList.toggle('player-active',workoutFocus.enabled);
 const overview=Boolean(workoutFocus.overview&&!workoutFocus.enabled);document.getElementById('app').classList.toggle('overview-active',overview);const overviewPanel=document.querySelector('.workout-overview');if(overviewPanel)overviewPanel.hidden=!overview;
 const setup=document.querySelector('.workout-setup');if(setup)setup.open=!workoutFocus.enabled;
 const intro=document.querySelector('.player-start');if(intro)intro.hidden=workoutFocus.enabled||overview;
 sections.forEach(s=>{s.hidden=overview|| (workoutFocus.enabled?s.dataset.playerStep!==(current?.exerciseId||current?.id):false);if(s.hidden)s.querySelectorAll('video').forEach(v=>v.pause());if(s.hidden)s.querySelectorAll('iframe').forEach(frame=>{const box=frame.parentElement;const button=document.createElement('button');button.className='primary';button.dataset.playVideo='';button.textContent='Play demonstration';box.replaceChildren(button)})});
 document.querySelectorAll('.player-set-entry').forEach(row=>{row.hidden=workoutFocus.enabled&&Number.isInteger(current?.setIndex)&&row.dataset.entryExercise===current.exerciseId&&Number(row.dataset.entryIndex)!==current.setIndex});
 document.querySelectorAll('[data-active-set-label]').forEach(label=>label.textContent=workoutFocus.enabled&&Number.isInteger(current?.setIndex)?current.name:'');
 const label=document.getElementById('focusPosition');if(label)label.textContent='Step '+(index+1)+' of '+steps.length+' · '+(index<steps.length-1?'Next: '+steps[index+1].name+'. ':'End of sequence. Review your actual entries before finishing. ')+'Swipe right for next, left for previous. Navigation never confirms a set.';
 const toggle=document.getElementById('focusToggle');if(toggle){toggle.textContent=workoutFocus.enabled?'Show all exercises':'Open workout player';toggle.setAttribute('aria-pressed',String(workoutFocus.enabled))}
 const select=document.querySelector('[aria-label="Jump to exercise"]');if(select)select.value=workoutFocus.id;
 document.querySelectorAll('[data-player-prev]').forEach(b=>b.disabled=index<=0);document.querySelectorAll('[data-player-next]').forEach(b=>b.disabled=index===steps.length-1);
 const phase=current?.phase;
 document.querySelectorAll('[data-player-phase]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.playerPhase===phase)));
}
function toggleWorkoutFocus(){workoutFocus.enabled=!workoutFocus.enabled;applyWorkoutFocus();if(workoutFocus.enabled)jumpWorkoutExercise('@warmup')}
function jumpWorkoutExercise(id){
 const plan=FormProgram.plan(data,activeProfile,selected,activeSessionId),step=FormPlayer.sequence(plan,activeLog()?.targetEdits).find(s=>s.id===id);if(!step)return;
 const section=[...document.querySelectorAll('[data-player-step]')].find(s=>s.dataset.playerStep===(step.exerciseId||id));if(!section)return;
 workoutFocus.id=id;workoutFocus.overview=false;workoutFocus.enabled=true;applyWorkoutFocus();section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});const heading=section.querySelector('h3');heading.tabIndex=-1;heading.focus({preventScroll:true});
}
function stepWorkoutExercise(delta){const ids=FormPlayer.sequence(FormProgram.plan(data,activeProfile,selected,activeSessionId),activeLog()?.targetEdits).map(s=>s.id),index=ids.indexOf(workoutFocus.id);if(ids.length)jumpWorkoutExercise(ids[Math.min(ids.length-1,Math.max(0,index+delta))])}
document.addEventListener('click',event=>{
 const phase=event.target.closest('[data-player-phase]');if(phase){const plan=FormProgram.plan(data,activeProfile,selected,activeSessionId),step=FormPlayer.sequence(plan,activeLog()?.targetEdits).find(s=>s.phase===phase.dataset.playerPhase);if(step)jumpWorkoutExercise(step.id)}
 if(event.target.closest('[data-edit-sequence]'))editWorkoutSequence();
 if(event.target.closest('[data-strength-sequence]'))reviewStrengthSequence();
});
function reviewStrengthSequence(){
 const plan=FormProgram.plan(data,activeProfile,selected,activeSessionId),r=routine(plan.routine.id),assertContext=editingContext(),ids=['back-squat','push-press','box-jumps','tricep-extension','leg-raise','deadbug'];
 if(!r||!ids.every(id=>ex(id)))return;
 trainingDialog('Supplied strength grouping','<p>Apply to this profile’s future, unstarted '+esc(r.name)+' sessions. Recorded plans and actual entries stay unchanged.</p><ol><li>Back squat — individual exercise</li><li>Two push-press preparation sets, with loads unspecified</li><li>Superset A: push press → box jumps, repeated three times</li><li>Circuit B: one-arm overhead tricep extension → hanging straight-leg raises → deadbug, repeated three times</li></ol><p>Push press has five sets total: two preparation sets with blank loads, then three working sets retaining the existing final three target loads. Box jumps and each Circuit B exercise have three sets. Repetition and rest targets, warm-up/cooldown instructions and other routine fields are retained. Additional exercises, if any, stay after these groups.</p><p class="notice">Rest between grouped exercises and rounds remains unspecified. One-arm repetition accounting remains as prescribed; no doubling is assumed.</p>',async()=>{assertContext();const p=FormPlayer.settings({routine:r}),phases={...p.phases},groups={...p.groups},standalone={...p.standalone};ids.forEach(id=>phases[id]='main');Object.assign(groups,{'back-squat':'','push-press':'A','box-jumps':'A','tricep-extension':'B','leg-raise':'B','deadbug':'B'});standalone['back-squat']=true;const prescriptions={...r.prescriptions};for(const id of ids.filter(id=>id!=='back-squat')){const target={...ex(id),...prescriptions[id]},count=id==='push-press'?5:3;const working=(target.weights||[]).slice(-3);while(working.length<3)working.unshift(null);prescriptions[id]={...prescriptions[id],reps:target.reps,rest:target.rest,kind:target.kind,sets:count,weights:id==='push-press'?[null,null,...working]:(target.weights||[]).slice(0,3)}}data=FormProgram.editRoutine(data,activeProfile,r.id,{ids:ids.concat(r.ids.filter(id=>!ids.includes(id))),prescriptions,player:{...p,phases,groups,standalone,preparation:{...p.preparation,'push-press':2},rounds:{...p.rounds,A:3,B:3}}});if(!await save())return false;render()});
}
function editWorkoutSequence(){
 const plan=FormProgram.plan(data,activeProfile,selected,activeSessionId),r=routine(plan.routine.id);if(!r){alert('This historical workout no longer has an editable routine.');return}
 const assertContext=editingContext(),p=FormPlayer.settings({routine:r});
 trainingDialog('Future workout sequence','<p>Enter only known clinician instructions. Saved sessions keep their original sequence and prescriptions. Numbered steps follow the saved exercise order within each phase. Assign the same group label to consecutive exercises only when the pairing is known. Two exercises form a superset; three or more form a circuit. Leave blank when unknown.</p><label class="field">Warm-up instructions<textarea name="warmup">'+esc(p.warmup||'')+'</textarea></label><label class="field">Cooldown instructions<textarea name="cooldown">'+esc(p.cooldown||'')+'</textarea></label>'+r.ids.map(id=>'<label class="field">'+esc(ex(id)?.name||id)+'<select data-phase-exercise="'+esc(id)+'">'+Object.entries(FormPlayer.phases).map(([value,name])=>'<option value="'+value+'"'+(FormPlayer.phase({routine:r},id)===value?' selected':'')+'>'+name+'</option>').join('')+'</select></label><label class="field">Group for '+esc(ex(id)?.name||id)+'<input type="text" maxlength="40" data-group-exercise="'+esc(id)+'" value="'+esc(FormPlayer.groupName({routine:r},id))+'" placeholder="None supplied"></label>').join('')+'<label class="field">Superset / circuit instructions<textarea name="groupInstructions">'+esc(typeof p.groupInstructions==='string'?p.groupInstructions:'')+'</textarea></label><p class="tiny muted">Enter supplied round counts and between-exercise / between-round rest. Exercise set counts are kept unchanged.</p>',async dialog=>{assertContext();const phases={...p.phases},groups={...p.groups};dialog.querySelectorAll('[data-group-exercise]').forEach(el=>groups[el.dataset.groupExercise]=el.value.trim());dialog.querySelectorAll('[data-phase-exercise]').forEach(el=>phases[el.dataset.phaseExercise]=el.value);const candidate={exercises:data.exercises,routine:{...r,player:{...p,phases,groups}}},steps=FormPlayer.exerciseSequence(candidate).filter(step=>!step.id.startsWith('@'));for(const name of new Set(r.ids.map(id=>groups[id]).filter(Boolean))){const members=steps.filter(step=>groups[step.id]===name),indices=members.map(step=>steps.indexOf(step));if(members.length<2||new Set(members.map(step=>step.phase)).size!==1||Math.max(...indices)-Math.min(...indices)+1!==members.length)throw Error('Group '+name+' needs at least two consecutive exercises in the same phase. Adjust the workout order in the exercise library if needed.')}data=FormProgram.editRoutine(data,activeProfile,r.id,{player:{...p,groups,groupInstructions:dialog.querySelector('[name=groupInstructions]').value,warmup:dialog.querySelector('[name=warmup]').value,cooldown:dialog.querySelector('[name=cooldown]').value,phases}});if(!await save())return false;render()});
}
function setEntryStatus(eid,index){const set=activeLog()?.sets.find(s=>s.exerciseId===eid&&s.index===index),label=document.getElementById('status-'+eid+'-'+index),button=document.getElementById('check-'+eid+'-'+index);if(label){label.textContent=set?.confirmed?'Confirmed':set?'Draft · confirm when complete':'Target only · not recorded';label.classList.toggle('is-confirmed',Boolean(set?.confirmed))}button?.setAttribute('aria-pressed',String(Boolean(set?.confirmed)))}
var autoRestEnabled=false;
function nextUnfinishedExercise(){const plan=FormProgram.plan(data,activeProfile,selected,activeSessionId),log=activeLog(),steps=FormPlayer.sequence(plan,activeLog()?.targetEdits).filter(s=>!s.id.startsWith('@')),ids=steps.map(s=>s.id),start=ids.indexOf(workoutFocus.id),ordered=ids.slice(start+1).concat(ids.slice(0,start+1));const next=ordered.find(stepId=>{const step=steps.find(s=>s.id===stepId),id=step.exerciseId||step.id,change=log?.changes?.[id];if(change?.status==='skipped'||change?.remainingSkipped)return false;const original=plan.exercises.find(e=>e.id===id),e=change?.replacement||{...original,...log?.targetEdits?.[id]};return (Number.isInteger(step.setIndex)&&!change?.replacement?[step.setIndex]:Array.from({length:e.sets},(_,index)=>index)).filter(index=>index<e.sets).some(index=>!log?.sets.some(s=>s.exerciseId===e.id&&s.index===index&&s.confirmed))});if(next)jumpWorkoutExercise(next);else{const label=document.getElementById('focusPosition');if(label)label.textContent='No unfinished target sets found. Review skips and actual results before finishing.'}}
function reviewSignalsHtml(){const signals=FormTraining.reviewSignals(data,currentDay());return '<details class="review-signals"><summary>Evidence-based review prompts ('+signals.length+')</summary><p class="tiny muted">A prompt requires two separate dates with every target set confirmed, matching saved targets and known loads. It does not establish readiness for progression. Unknown loads, drafts, substitutions and changed prescriptions prevent a prompt.</p>'+(signals.length?signals.map(s=>'<div class="review-card"><strong>'+esc(s.name)+' · targets matched twice</strong><p class="tiny">'+s.dates.join(' and ')+' · '+s.sets+' sets × '+s.reps+' '+(s.kind==='seconds'?'seconds':'reps')+'</p><button class="ghost" data-signal-routine="'+esc(s.routine)+'" data-signal-exercise="'+esc(s.exercise)+'">Review these results</button></div>').join(''):'<p class="muted tiny">No matching evidence yet. This does not mean your training is unsuccessful.</p>')+'</details>'}
function weeklyTraining(){return '<section class="section panel"><h2>Weekly training</h2><p class="tiny muted">Confirmed results only. A recorded training day can contain partial workouts. These counts are not an adherence score.</p><div class="row"><label class="field">Period<select id="weeklyPeriod" data-action-change="drawWeeklyTraining()"><option value="8">8 weeks</option><option value="26">26 weeks</option><option value="52">52 weeks</option></select></label><label class="field">Measure<select id="weeklyMeasure" data-action-change="drawWeeklyTraining()"><option value="sets">Confirmed sets</option><option value="days">Training days</option><option value="sessions">Sessions with confirmed sets</option><option value="volume">External-load volume</option><option value="minutes">Confirmed activity minutes</option></select></label></div><div id="weeklyChart"></div><p id="weeklyDetail" role="status"></p></section>'}
function drawWeeklyTraining(){const el=document.getElementById('weeklyChart');if(!el)return;const rows=FormTraining.weekly(data,currentDay(),Number(document.getElementById('weeklyPeriod').value)),measure=document.getElementById('weeklyMeasure').value,max=Math.max(1,...rows.map(r=>r[measure]));el.innerHTML='<div class="performance-bars">'+rows.map(r=>'<button class="ghost" data-week="'+r.from+'" aria-label="Week beginning '+r.from+'"><span style="height:'+Math.max(2,r[measure]/max*100)+'px"></span><b>'+Math.round(r[measure]*10)/10+'</b><small>'+r.from.slice(5)+'</small></button>').join('')+'</div>';document.getElementById('weeklyDetail').textContent='Select a week for its breakdown.'}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.signalRoutine)newProgression(b.dataset.signalRoutine,b.dataset.signalExercise);if(b.dataset.week){const row=FormTraining.weekly(data,currentDay(),Number(document.getElementById('weeklyPeriod').value)).find(r=>r.from===b.dataset.week);if(row)document.getElementById('weeklyDetail').textContent=row.from+' to '+row.to+': '+row.days+' training days · '+row.sessions+' sessions · '+row.sets+' confirmed sets · '+Math.round(row.volume)+' kg × reps · '+Math.round(row.minutes)+' activity minutes.'}});
var progressSection='Overview';
const progressGroups={'Confirmed external-load volume':'History','Performance explorer':'History','Weekly training':'Overview','Progression reviews':'Reviews','Long-term training framework':'Reviews','Your training review':'Reviews','Activities':'Activities','Activity totals':'Activities','Recorded weight trend':'Measurements','Custom measurements':'Measurements','Body measurements':'Measurements'};
function progressNavigation(){return '<nav class="progress-navigation" aria-label="Progress reports">'+['Overview','History','Reviews','Activities','Measurements','All reports'].map(name=>'<button type="button" class="tab" data-progress-section="'+name+'" aria-pressed="false">'+name+'</button>').join('')+'</nav>'}
function applyProgressSection(){document.querySelectorAll('#app > section').forEach(section=>{const group=progressGroups[section.querySelector('h2')?.textContent];section.hidden=Boolean(group&&progressSection!=='All reports'&&progressSection!==group)});const stats=document.querySelector('#app > .stats');if(stats)stats.hidden=!['Overview','All reports'].includes(progressSection);document.querySelectorAll('[data-progress-section]').forEach(b=>{const active=b.dataset.progressSection===progressSection;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
document.addEventListener('click',event=>{const b=event.target.closest('[data-progress-section]');if(b){progressSection=b.dataset.progressSection;applyProgressSection()}});

function reportTotals(){return FormTraining.reviewSummary(data,'0001-01-01',currentDay(),currentDay())}

// A modal may outlive the profile or session that opened it. Never redirect its save.
function editingContext(sessionScoped=true){const profile=activeProfile,sourceStore=store,date=selected,id=activeSessionId;return ()=>{if(activeProfile!==profile||store!==sourceStore)throw Error('Profile changed. Close this form and reopen it for the intended profile.');if(sessionScoped&&(selected!==date||activeSessionId!==id))throw Error('Session changed. Close this form and reopen it for the intended workout.')}}
function dashboardSessions(rows){return rows.length?'<div class="history-list" aria-label="Selected day sessions">'+rows.map((r,i)=>'<button class="ghost history-row" data-dashboard-session="'+esc(r.id)+'"><strong>'+esc(r.plan.routine.name)+'</strong><span>Session '+(i+1)+' · '+esc(r.status)+'</span><small>'+r.confirmed+' confirmed sets'+(r.drafts?' · '+r.drafts+' drafts':'')+'</small></button>').join('')+'</div>':''}
document.addEventListener('click',event=>{const b=event.target.closest('[data-dashboard-session]');if(b){if(activeSessionId!==b.dataset.dashboardSession)stopTimer();activeSessionId=b.dataset.dashboardSession;view='Workout';render()}});

function editExerciseDetails(id){const original=ex(id);if(!original)return;trainingDialog('Edit my exercise instructions','<p>'+esc(original.name)+'. Saved session instructions stay unchanged. This edits your library notes; reviewed reference guides remain separate.</p>'+[['instructions','My instructions'],['equipment','Equipment'],['notes','My notes'],['video','My demonstration link (HTTPS)']].map(([key,label])=>'<label class="field">'+label+(key==='video'?'<input name="'+key+'" type="url" value="'+esc(original[key]||'')+'">':'<textarea name="'+key+'">'+esc(original[key]||'')+'</textarea>')+'</label>').join(''),async dialog=>{const fields=Object.fromEntries(['instructions','equipment','notes','video'].map(key=>[key,dialog.querySelector('[name='+key+']').value.trim()]));if(fields.video&&!/^https:\/\//i.test(fields.video))throw Error('Use an HTTPS demonstration link.');const next=FormProgram.preserve(data,activeProfile),exercise=next.exercises.find(e=>e.id===id);if(!exercise)throw Error('Exercise no longer available.');Object.assign(exercise,fields);data=next;if(!await save())return false;render()})}

function progressionRulesHtml(){return '<details><summary>My automatic review rules ('+(data.progressionRules||[]).filter(r=>r.enabled).length+' enabled)</summary><p class="tiny">Rules prepare review drafts after you finish a session with qualifying evidence. They never change prescriptions or confirm readiness. Changed guidance or exercise preferences pauses a rule for review. Avoid/review preferences must be resolved before enabling progression.</p><button class="secondary" data-action-click="editProgressionRule()">Set a review rule</button><div class="history-list">'+(data.progressionRules||[]).map((r,i)=>'<button class="ghost history-row" data-edit-rule="'+i+'"><strong>'+esc(ex(r.exercise)?.name||r.exercise)+'</strong><span>'+esc(routine(r.routine)?.name||r.routine)+' · +'+r.increment+' '+(r.metric==='load'?'kg per set':r.kind==='seconds'?'seconds':'reps')+'</span><small>'+esc(FormProgressionRules.pauseReason(data,r)||'Enabled · drafts require approval')+'</small></button>').join('')+'</div></details>'}
function editProgressionRule(index){const existing=data.progressionRules?.[index],options=data.routines.flatMap(r=>r.ids.map(id=>({r,id})));if(existing&&!options.some(o=>o.r.id===existing.routine&&o.id===existing.exercise))options.push({r:routine(existing.routine),id:existing.exercise});if(!options.length){alert('Add movements to a workout first.');return}const d=trainingDialog('My automatic review rule','<p>Choose your own increment, aligned with any clinician guidance. After two separate qualifying sessions, finishing a session can prepare a draft for your approval. No default increment is provided.</p><label class="field">Workout and movement<select name="movement">'+options.map((o,i)=>'<option value="'+i+'">'+esc(o.r.name+' · '+ex(o.id).name)+'</option>').join('')+'</select></label><label class="field">Change<select name="metric"><option value="reps">Repetitions / seconds</option><option value="load">External load per set (kg)</option></select></label><label class="field">My increment<input name="increment" type="number" min="0.001" step="any" required></label><label class="row"><input name="enabled" type="checkbox"> Enable automatic review drafts</label><p class="tiny">Saved guidance: '+esc(data.restrictions||'None entered')+'</p><label class="row"><input name="reviewed" type="checkbox" required> I have reviewed this rule and relevant guidance</label>',async dialog=>{const o=options[Number(dialog.querySelector('[name=movement]').value)];data=FormProgressionRules.configure(data,{routine:o.r.id,exercise:o.id,metric:dialog.querySelector('[name=metric]').value,increment:Number(dialog.querySelector('[name=increment]').value),enabled:dialog.querySelector('[name=enabled]').checked});if(!await save())return false;render()});if(existing){d.querySelector('[name=movement]').value=String(options.findIndex(o=>o.r.id===existing.routine&&o.id===existing.exercise));d.querySelector('[name=movement]').disabled=true;d.querySelector('[name=metric]').value=existing.metric;d.querySelector('[name=increment]').value=existing.increment;d.querySelector('[name=enabled]').checked=existing.enabled}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-edit-rule]');if(b)editProgressionRule(Number(b.dataset.editRule))});
